export type { HSTSOptions, SecurityHeadersOptions } from "./headers";
export {
  getSecurityHeaders,
  applySecurityHeaders,
  stripFingerprintHeaders,
} from "./headers";

export type { CSPSource, CSPDirectives } from "./csp";
export {
  CSP_HEADER,
  CSP_REPORT_ONLY_HEADER,
  buildCSP,
  generateNonce,
  strictCspWithNonce,
} from "./csp";

export { isTrustedOrigin, assertTrustedOrigin } from "./origin";

// HSTS: OSHP explicitly recommends omitting `preload` by default.
// hstspreload.org warns against including it without understanding the permanent consequences.
const HSTS_ONE_YEAR = 31_536_000;

// Permissions-Policy: deny the most commonly abused sensor and capture APIs.
// fullscreen and picture-in-picture are left open (*) to avoid breaking common UX.
const DEFAULT_PERMISSIONS_POLICY = [
  "accelerometer=()",
  "camera=()",
  "display-capture=()",
  "encrypted-media=()",
  "geolocation=()",
  "gyroscope=()",
  "magnetometer=()",
  "microphone=()",
  "midi=()",
  "payment=()",
  "publickey-credentials-get=()",
  "screen-wake-lock=()",
  "usb=()",
  "web-share=()",
  "xr-spatial-tracking=()",
].join(", ");

// Headers that leak implementation details and should be removed in production.
// Source: OWASP OSHP "Headers to Remove" list.
const FINGERPRINT_HEADERS = [
  "Server",
  "X-Powered-By",
  "X-AspNet-Version",
  "X-AspNetMvc-Version",
  "X-Generator",
] as const;

export interface HSTSOptions {
  /** Seconds the browser should remember HTTPS-only. Default: 31536000 (1 year). */
  maxAge?: number;
  /** Apply HSTS to all subdomains. Default: true. */
  includeSubDomains?: boolean;
  /**
   * Request inclusion in browser preload lists.
   * WARNING: Permanent and very difficult to undo. Requires 2-year max-age
   * and all subdomains on HTTPS. Do not set without understanding the consequences.
   */
  preload?: boolean;
}

export interface SecurityHeadersOptions {
  /**
   * Strict-Transport-Security configuration.
   * Set to false to omit (e.g., non-HTTPS environments, local dev).
   */
  hsts?: HSTSOptions | false;
  /**
   * X-Frame-Options value. Default: "DENY".
   * frame-ancestors in CSP supersedes this for modern browsers;
   * include both for compatibility with older browsers.
   * Set to false to omit.
   */
  frameOptions?: "DENY" | "SAMEORIGIN" | false;
  /**
   * Permissions-Policy header value.
   * Pass a custom string to override the default restrictive policy.
   * Set to false to omit.
   */
  permissionsPolicy?: string | false;
  /**
   * Cross-Origin-Embedder-Policy: require-corp.
   * Enables SharedArrayBuffer but requires all cross-origin resources to opt in
   * via CORS or CORP. Off by default — audit cross-origin dependencies first.
   */
  coep?: boolean;
  /** Additional headers merged into the response verbatim. */
  extra?: Record<string, string>;
}

function buildHSTS(opts: HSTSOptions): string {
  const maxAge = opts.maxAge ?? HSTS_ONE_YEAR;
  const parts = [`max-age=${maxAge}`];
  if (opts.includeSubDomains !== false) parts.push("includeSubDomains");
  if (opts.preload) parts.push("preload");
  return parts.join("; ");
}

/**
 * Returns the OWASP OSHP recommended security headers as a plain object.
 * Does not include Content-Security-Policy — generate that separately with buildCSP / strictCspWithNonce.
 */
export function getSecurityHeaders(
  options: SecurityHeadersOptions = {},
): Record<string, string> {
  const headers: Record<string, string> = {};

  if (options.hsts !== false) {
    headers["Strict-Transport-Security"] = buildHSTS(
      options.hsts && typeof options.hsts === "object" ? options.hsts : {},
    );
  }

  // Prevent MIME-type sniffing attacks.
  headers["X-Content-Type-Options"] = "nosniff";

  // Clickjacking protection — still needed for browsers without frame-ancestors CSP support.
  if (options.frameOptions !== false) {
    headers["X-Frame-Options"] = options.frameOptions ?? "DENY";
  }

  // Disable the legacy XSS Auditor. OSHP recommends setting this to 0:
  // the auditor causes information leakage and modern browsers have removed it.
  headers["X-XSS-Protection"] = "0";

  // Strip path/query from the Referer header on cross-origin requests.
  headers["Referrer-Policy"] = "strict-origin-when-cross-origin";

  // Isolates browsing context to same-origin. Mitigates window.opener attacks and XS-Leaks.
  headers["Cross-Origin-Opener-Policy"] = "same-origin";

  // Prevents other origins from loading this resource (Spectre mitigation).
  headers["Cross-Origin-Resource-Policy"] = "same-origin";

  // Restrict Adobe Flash / Acrobat cross-domain policy file access.
  headers["X-Permitted-Cross-Domain-Policies"] = "none";

  if (options.permissionsPolicy !== false) {
    headers["Permissions-Policy"] =
      options.permissionsPolicy ?? DEFAULT_PERMISSIONS_POLICY;
  }

  // COEP is opt-in: enabling it without auditing cross-origin dependencies breaks integrations.
  if (options.coep) {
    headers["Cross-Origin-Embedder-Policy"] = "require-corp";
  }

  if (options.extra) {
    for (const [name, value] of Object.entries(options.extra)) {
      headers[name] = value;
    }
  }

  return headers;
}

/**
 * Applies OWASP security headers to a Response, returning a new Response.
 * The original Response is not mutated. Framework-agnostic: works in edge middleware,
 * route handlers, or service workers.
 */
export function applySecurityHeaders(
  response: Response,
  options?: SecurityHeadersOptions,
): Response {
  const securityHeaders = getSecurityHeaders(options);
  const next = new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers: response.headers,
  });
  for (const [name, value] of Object.entries(securityHeaders)) {
    next.headers.set(name, value);
  }
  return next;
}

/**
 * Removes server-fingerprinting headers from a Response, returning a new Response.
 * Strips: Server, X-Powered-By, X-AspNet-Version, X-AspNetMvc-Version, X-Generator.
 */
export function stripFingerprintHeaders(response: Response): Response {
  const next = new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers: response.headers,
  });
  for (const name of FINGERPRINT_HEADERS) {
    next.headers.delete(name);
  }
  return next;
}

import { randomBytes, toBase64url } from "{{scope}}/crypto";

export const CSP_HEADER = "Content-Security-Policy";
export const CSP_REPORT_ONLY_HEADER = "Content-Security-Policy-Report-Only";

/**
 * A single CSP source expression.
 * Examples: "'self'", "'none'", "'strict-dynamic'", "'nonce-abc123'",
 *           "https://cdn.example.com", "'sha256-xyz...'".
 */
export type CSPSource = string;

/**
 * Typed CSP directive map. Boolean directives (upgrade-insecure-requests,
 * block-all-mixed-content) are set with `true`; `false` or absence omits them.
 */
export interface CSPDirectives {
  "default-src"?: CSPSource[];
  "script-src"?: CSPSource[];
  "style-src"?: CSPSource[];
  "img-src"?: CSPSource[];
  "connect-src"?: CSPSource[];
  "font-src"?: CSPSource[];
  "media-src"?: CSPSource[];
  "object-src"?: CSPSource[];
  "frame-src"?: CSPSource[];
  "worker-src"?: CSPSource[];
  "child-src"?: CSPSource[];
  "manifest-src"?: CSPSource[];
  "frame-ancestors"?: CSPSource[];
  "base-uri"?: CSPSource[];
  "form-action"?: CSPSource[];
  sandbox?: CSPSource[];
  "report-uri"?: string[];
  "report-to"?: string[];
  "upgrade-insecure-requests"?: boolean;
  "block-all-mixed-content"?: boolean;
}

/**
 * Serializes a CSPDirectives object to a Content-Security-Policy header value string.
 * Directive ordering follows insertion order of the object.
 */
export function buildCSP(directives: CSPDirectives): string {
  const parts: string[] = [];

  for (const key of Object.keys(directives) as Array<keyof CSPDirectives>) {
    const value = directives[key];
    if (value === undefined) continue;
    if (typeof value === "boolean") {
      if (value) parts.push(key);
      continue;
    }
    if (value.length > 0) {
      parts.push(`${key} ${value.join(" ")}`);
    }
  }

  return parts.join("; ");
}

/**
 * Generates a cryptographically strong nonce for use in a CSP script-src directive.
 * Returns a base64url-encoded string (no padding). Each page load should get a fresh nonce.
 *
 * Uses randomBytes from @scope/crypto (CSPRNG via getRandomValues) — 16 bytes = 128 bits entropy.
 */
export function generateNonce(): string {
  return toBase64url(randomBytes(16));
}

/**
 * Builds a strict nonce-based CSP policy following the OWASP CSP Cheat Sheet.
 *
 * Why nonce + strict-dynamic?
 * Static source allowlists are fragile: a single compromised CDN or inline script
 * bypasses the policy entirely. Nonces cryptographically bind each allowed script
 * to the server response that generated it. `strict-dynamic` propagates trust to
 * scripts loaded by nonce-trusted scripts, enabling module-based applications
 * without listing every source. `unsafe-inline` and `unsafe-eval` are excluded.
 *
 * @param nonce - The nonce generated by generateNonce() for this response.
 * @param extra - Optional overrides/additions merged on top of the strict default.
 *                Passing a key overrides the default value for that directive.
 */
export function strictCspWithNonce(
  nonce: string,
  extra?: CSPDirectives,
): string {
  const base: CSPDirectives = {
    "default-src": ["'self'"],
    "script-src": [`'nonce-${nonce}'`, "'strict-dynamic'"],
    "style-src": ["'self'"],
    "img-src": ["'self'", "data:"],
    "connect-src": ["'self'"],
    "font-src": ["'self'"],
    "object-src": ["'none'"],
    "base-uri": ["'none'"],
    "form-action": ["'self'"],
    "frame-ancestors": ["'none'"],
    "upgrade-insecure-requests": true,
  };

  return buildCSP({ ...base, ...extra });
}

// Methods that mutate server state and require origin verification.
// GET, HEAD, OPTIONS are excluded — they are safe and should not require CSRF protection.
const MUTATING_METHODS = new Set(["POST", "PUT", "PATCH", "DELETE"]);

/**
 * Returns true if the request's origin is trusted.
 *
 * For non-mutating methods (GET, HEAD, OPTIONS) this always returns true —
 * CSRF attacks require state-changing requests.
 *
 * For mutating methods:
 * - A missing Origin header is rejected. Modern browsers always send Origin on
 *   cross-site fetches; its absence on a mutating request is suspicious.
 * - Same-origin requests (Origin matches request URL's origin) are accepted.
 * - Origins in the explicit allowlist are accepted.
 * - Everything else is rejected.
 *
 * @param request - The incoming Fetch API Request.
 * @param allowedOrigins - Optional list of trusted cross-origins (e.g. ["https://app.example.com"]).
 */
export function isTrustedOrigin(
  request: Request,
  allowedOrigins?: string[],
): boolean {
  if (!MUTATING_METHODS.has(request.method.toUpperCase())) return true;

  const origin = request.headers.get("Origin");
  if (!origin) return false;

  const url = new URL(request.url);
  const requestOrigin = `${url.protocol}//${url.host}`;

  if (origin === requestOrigin) return true;
  if (allowedOrigins && allowedOrigins.includes(origin)) return true;

  return false;
}

/**
 * Returns a 403 Response if the request's origin is not trusted, null otherwise.
 * Designed for early-return guards at the top of route handlers or middleware:
 *
 * ```ts
 * const guard = assertTrustedOrigin(request);
 * if (guard) return guard;
 * ```
 *
 * @param request - The incoming Fetch API Request.
 * @param allowedOrigins - Optional list of trusted cross-origins.
 */
export function assertTrustedOrigin(
  request: Request,
  allowedOrigins?: string[],
): Response | null {
  if (isTrustedOrigin(request, allowedOrigins)) return null;
  return new Response("Forbidden", { status: 403 });
}
